<script setup lang="ts">
import {ref,computed,onMounted,watch,nextTick} from 'vue'
import {useRoute} from 'vue-router'
import {api} from '../store'
import GraphCanvas from './GraphCanvas.vue'
import NeuralGraphCanvas from './NeuralGraphCanvas.vue'
import SealUniverse from './SealUniverse.vue'
import {IconMaximize,IconMinimize,IconDatabase,IconRoute} from '@tabler/icons-vue'
import './neural-space.css'
import type {GraphData,GraphEdge} from './types'
const data=ref<GraphData|null>(null),q=ref(''),kind=ref(''),source=ref(''),status=ref(''),loading=ref(false),error=ref(''),notice=ref(''),selected=ref(''),selectedType=ref('node'),pathIds=ref<string[]>([]),start=ref(''),end=ref(''),pathText=ref(''),importOpen=ref(false),importText=ref(''),reviewer=ref(''),reviewNote=ref(''),saving=ref(false)
const initialRoute=useRoute()
q.value=String(initialRoute.query.q||'')
selected.value=String(initialRoute.query.node||initialRoute.query.edge||'');selectedType.value=initialRoute.query.edge?'edge':'node'
const modalEl=ref<HTMLElement>();let returnFocus:HTMLElement|null=null
const layout=ref<'neural'|'radial'|'hierarchy'>('neural'),center=ref(''),depth=ref(1),assertionSource=ref(''),immersive=ref(innerWidth>=1000),sourceOpen=ref(false),pathOpen=ref(false)
center.value=String(initialRoute.query.node||'')
const exhibition=ref(initialRoute.query.view!=='network'),lastExhibitSeal=ref('')
function allExhibitData(){q.value='';kind.value='';source.value='';status.value='';assertionSource.value='';load()}
function openWorkbench(id?:string,type:'node'|'edge'='node'){if(id)select(id,type);exhibition.value=false}
watch(importOpen,async open=>{if(open){returnFocus=document.activeElement as HTMLElement;await nextTick();modalEl.value?.querySelector<HTMLButtonElement>('button')?.focus()}else{returnFocus?.focus()}})
function modalKey(event:KeyboardEvent){if(event.key==='Escape'){importOpen.value=false;return}if(event.key!=='Tab')return;const items=Array.from(modalEl.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input,textarea,a[href]')||[]);if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
const activeNode=computed(()=>selectedType.value==='node'?data.value?.nodes.find(n=>n.id===selected.value):undefined)
const activeEdge=computed(()=>selectedType.value==='edge'?data.value?.edges.find(n=>n.id===selected.value):undefined)
const relations=computed(()=>activeEdge.value?[activeEdge.value]:data.value?.edges.filter(e=>e.source===selected.value||e.target===selected.value)||[])
const nodeGroups=computed(()=>['resource','seal_object','seal_draft','character','script','seal_type','collection','document','person','period','place'].map(k=>({kind:k,title:data.value?.kinds[k]||k,nodes:data.value?.nodes.filter(n=>n.kind===k)||[]})).filter(g=>g.nodes.length))
const nodeFacts=computed(()=>{const n=activeNode.value;if(!n)return [];const outgoing=(predicate:string)=>{const ids=data.value?.edges.filter(e=>e.source===n.id&&e.predicate===predicate).map(e=>label(e.target))||[];return [...new Set(ids)].join('、')||'当前资料未收录'};if(n.kind==='seal_object')return [['官方定名',n.attributes.official_title],['中文印文',n.attributes.transcription],['馆藏机构',n.attributes.museum],['文物号',n.attributes.accession_number],['年代（官方）',n.attributes.period],['材质（官方）',n.attributes.material],['尺寸（官方）',n.attributes.dimensions],['核对范围','官方馆藏记录；不是系统独立鉴定']];if(n.kind==='seal_draft')return [['印文',n.attributes.transcription||n.label],['书体',outgoing('has_script')],['类型',outgoing('has_type')],['页面来源',outgoing('cites_collection')],['创作者','尚无核验资料'],['年代 / 馆藏','尚无核验资料']];if(n.kind==='character')return [['汉字',n.label],['Unicode','U+'+n.label.codePointAt(0)!.toString(16).toUpperCase()],['相关印稿',String(new Set(relations.value.map(e=>e.source)).size)+' 条（当前筛选）'],['释义 / 字源','尚无核验资料']];if(n.kind==='resource'){const s=data.value?.sources.find(s=>s.id===n.attributes.source_id);return [['接入状态',s?sourceStates[s.access_state]||s.access_state:'待核验'],['已登记页面',String(data.value?.receipts.filter(d=>d.source_id===s?.id).length||0)],['说明',s?.note||'待补充']]};return [['节点类别',n.kind_label],['名称',n.label],['说明',n.kind==='collection'?'指原网页的“来源”栏，不推断为作者或博物馆。':'以下关联来自页面文字或人工核验意见。']]})
const label=(id:string)=>data.value?.nodes.find(n=>n.id===id)?.label||id
const doc=(id:string)=>data.value?.documents.find(d=>d.id===id)
const sourceStates:Record<string,string>={homepage_only:'首页已核对 · 目录待接入',selected_metadata_verified:'已核对14条选定详情',three_records_verified:'已核对3条详情',official_object_records:'已核对官方馆藏记录，范围见说明',resource_index_only:'已核对资源入口',official_service_notice:'官方服务文献已核对'}
function params(){return new URLSearchParams({q:q.value.trim(),kind:kind.value,source:source.value,status:status.value,assertion_source:assertionSource.value})}
const exportUrl=(format:string)=>'/api/graph/export?'+params().toString()+'&format='+format
async function load(){loading.value=true;error.value='';pathIds.value=[];pathText.value='';try{const result=await api<GraphData>('/graph?'+params());data.value=result;const preferred=result.nodes.find(n=>n.matched&&n.id==='node-82168367d28b8e3a25bd8b93842b')||result.nodes.find(n=>n.matched&&n.kind==='seal_object')||result.nodes.find(n=>n.matched&&n.kind==='seal_draft')||result.nodes.find(n=>n.matched)||result.nodes[0];const keep=selectedType.value==='edge'?result.edges.some(e=>e.id===selected.value):result.nodes.some(n=>n.id===selected.value&&n.matched);if(!keep){selected.value=preferred?.id||'';selectedType.value='node'}if(!result.nodes.some(n=>n.id===center.value&&n.matched))center.value=preferred?.id||'';const seals=result.nodes.filter(n=>n.kind==='seal_draft');if(!result.nodes.some(n=>n.id===start.value))start.value=seals[0]?.id||'';if(!result.nodes.some(n=>n.id===end.value))end.value=seals[1]?.id||''}catch(e){error.value=e instanceof Error?e.message:'图谱读取失败'}finally{loading.value=false}}
function select(id:string,type:'node'|'edge'){selected.value=id;selectedType.value=type;reviewNote.value=''}
async function findPath(){error.value='';try{const filter=params();filter.set('start',start.value);filter.set('end',end.value);const p=await api('/graph/path?'+filter);pathText.value=p.found?p.nodes.map((n:any)=>n.label).join(' → ')+' · '+p.notice:p.notice;pathIds.value=[...p.nodes.map((n:any)=>n.id),...p.edges.map((e:any)=>e.id)]}catch(e){error.value=e instanceof Error?e.message:'路径读取失败'}}
async function importClaims(){saving.value=true;error.value='';try{if(importText.value.length>200000)throw new Error('导入内容请控制在200KB以内');if(importText.value.includes('请填写'))throw new Error('请把模板占位文字替换为核对过的实际资料');const result=await api('/graph/imports',{method:'POST',body:JSON.stringify(JSON.parse(importText.value))});notice.value=result.notice;importOpen.value=false;status.value='candidate';q.value='';kind.value='';source.value='';assertionSource.value='';await load();select(result.edge_ids[0],'edge')}catch(e){error.value=e instanceof Error?e.message:'导入失败'}finally{saving.value=false}}
async function review(edge:GraphEdge,decision:string){saving.value=true;error.value='';try{await api('/graph/edges/'+edge.id+'/review',{method:'POST',body:JSON.stringify({decision,reviewer:reviewer.value,note:reviewNote.value})});notice.value=decision==='rejected'?'已排除这条线索，复核记录已保存':'已保存人工复核记录；可在“人工复核”筛选中查看';await load()}catch(e){error.value=e instanceof Error?e.message:'复核保存失败'}finally{saving.value=false}}
function template(){importText.value=JSON.stringify({source_id:'fudan',url:'https://yin.fudan.edu.cn/',title:'请填写具体条目标题',note:'请填写该页面上支持关系的文字依据；首页不能代替具体条目。',claims:[{subject:{label:'请填写印稿名称',kind:'seal_draft'},predicate:'has_script',object:{label:'请填写页面记载书体',kind:'script'}}]},null,2)}
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file){if(file.size>200000){error.value='文件超过200KB';return}importText.value=await file.text()}}
onMounted(load)
</script>
<template>
<SealUniverse :direct-reading="Boolean(initialRoute.query.node||initialRoute.query.edge)" v-if="exhibition" :data="data" :selected="selected" :selected-type="selectedType" :loading="loading" :error="error" :initial-anchor="lastExhibitSeal" @anchor="lastExhibitSeal=$event" @full="allExhibitData" @select="select" @workbench="openWorkbench" @retry="load"/>
<main v-else class="kg-page" :class="{'kg-immersive':immersive,'kg-sources-open':sourceOpen,'kg-path-open':pathOpen}">
 <header class="kg-header"><div><button class="kg-back kg-return-exhibit" @click="exhibition=true">‹ 回到方寸宇宙</button><h1>印学知识图谱 <small>NEURAL ARCHIVE</small></h1><p>把印稿、汉字与资料出处连起来。点击节点或关系，查看支持它的网页。</p></div><div class="kg-header-actions"><button v-if="immersive" :aria-pressed="sourceOpen" @click="sourceOpen=!sourceOpen;pathOpen=false"><IconDatabase :size="14"/>资料来源</button><button v-if="immersive" :aria-pressed="pathOpen" @click="pathOpen=!pathOpen;sourceOpen=false"><IconRoute :size="14"/>关联路径</button><button @click="immersive=!immersive"><IconMinimize v-if="immersive" :size="15"/><IconMaximize v-else :size="15"/>{{immersive?'退出沉浸':'沉浸式空间'}}</button><button @click="importOpen=true;template()">导入资料线索</button><RouterLink to="/workspace">处理工作台 ↗</RouterLink></div></header>
 <div v-if="error" class="kg-message kg-error" role="alert">{{error}}<button aria-label="关闭错误" @click="error=''">×</button></div><div v-if="notice" class="kg-message" role="status">{{notice}}<button aria-label="关闭提示" @click="notice=''">×</button></div>
 <section class="kg-sources" aria-label="资料来源接入情况"><article v-for="s in data?.sources" :key="s.id" :class="{chosen:source===s.id}"><div><b>{{s.priority===1?'优先来源':'来源 0'+s.priority}}</b><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title}} ↗</a></div><span>{{sourceStates[s.access_state]||s.access_state}}</span><p>{{s.note}}</p><button @click="source=source===s.id?'':s.id;load()">{{source===s.id?'取消筛选':'查看相关节点'}}</button></article></section>
 <form class="kg-toolbar" @submit.prevent="load"><label class="kg-search">搜索印文或汉字<input v-model="q" placeholder="例如：人生、梦、小篆" aria-label="搜索图谱节点"></label><label>节点类型<select v-model="kind" @change="load"><option value="">全部类型</option><option v-for="(v,k) in data?.kinds" :value="k">{{v}}</option></select></label><label>来源方式<select v-model="assertionSource" @change="load"><option value="">全部方式</option><option value="page_fetched">公开页面提取</option><option value="manual_citation">手工引用</option></select></label><label>关系状态<select v-model="status" @change="load"><option value="">有据关系</option><option v-for="(v,k) in data?.statuses" :value="k">{{v}}</option></select></label><button class="kg-primary" :disabled="loading">{{loading?'读取中…':'检索图谱'}}</button><button type="button" @click="q='';kind='';source='';status='';assertionSource='';load()">重置</button><div class="kg-export"><span>导出当前筛选</span><a :href="exportUrl('json')">JSON ↓</a><a :href="exportUrl('turtle')">RDF ↓</a><a :href="exportUrl('json-ld')">JSON-LD ↓</a></div></form>
 <div class="kg-summary"><b>{{data?.counts.nodes||0}} <span>节点</span></b><b>{{data?.counts.edges||0}} <span>有出处关系</span></b><b>{{data?.counts.documents||0}} <span>关系支持页面</span></b><p>匹配 {{data?.counts.matched||0}} · 上下文 {{data?.counts.context||0}} · 登记凭证 {{data?.counts.receipts||0}} 页。无推断人物、朝代或传承关系。{{data?.limited?'结果超过500个节点，请缩小筛选。':''}}</p></div>
 <section class="kg-workspace">
 <aside class="kg-panel kg-node-panel"><header><h2>分层资料目录</h2><small>平台 → 印稿 → 汉字与属性</small></header><div class="kg-node-list"><details v-for="g in nodeGroups" :key="g.kind" open><summary>{{g.title}} <small>{{g.nodes.length}}</small></summary><button v-for="n in g.nodes" :key="n.id" :class="{selected:selected===n.id}" @click="select(n.id,'node')"><i :class="n.kind"></i><span>{{n.label}}<small>{{n.matched?n.kind_label:'上下文 · '+n.kind_label}}</small></span><b>›</b></button></details><p v-if="!loading&&!data?.nodes.length">暂无匹配节点。</p></div></aside>
 <div class="kg-center"><div class="kg-network kg-panel"><header><h2>资料关联网络</h2><span>点击节点看详情 · 点击连线看依据</span></header><div class="kg-layoutbar"><div class="kg-layout-tabs" aria-label="图谱布局"><button :aria-pressed="layout==='neural'" :class="{active:layout==='neural'}" @click="layout='neural'">三维空间</button><button :aria-pressed="layout==='radial'" :class="{active:layout==='radial'}" @click="layout='radial'">中心辐射</button><button :aria-pressed="layout==='hierarchy'" :class="{active:layout==='hierarchy'}" @click="layout='hierarchy'">分层结构</button></div><label>中心<select v-model="center" aria-label="选择布局中心" @change="select(center,'node')"><option v-for="n in data?.nodes" :value="n.id">{{n.label}}</option></select></label><label>展开<select v-model.number="depth" aria-label="选择展开层级"><option :value="1">一层关联</option><option :value="2">二层关联</option><option :value="0">全部节点</option></select></label></div><NeuralGraphCanvas v-if="layout==='neural'" :data="data" :selected="selected" :path="pathIds" :center="center" :depth="depth" @select="select" @fallback="layout='radial'"/><GraphCanvas v-else :data="data" :selected="selected" :path="pathIds" :layout="layout==='hierarchy'?'hierarchy':'radial'" :center="center" :depth="depth" @select="select"/><footer class="kg-legend"><span v-for="g in nodeGroups"><i :class="g.kind"></i>{{g.title}}</span></footer></div>
 <form class="kg-panel kg-path" @submit.prevent="findPath"><h2>查找资料关联</h2><div><select v-model="start" aria-label="路径起点"><option value="">选择起点</option><option v-for="n in data?.nodes" :value="n.id">{{n.label}} · {{n.kind_label}}</option></select><span>→</span><select v-model="end" aria-label="路径终点"><option value="">选择终点</option><option v-for="n in data?.nodes" :value="n.id">{{n.label}} · {{n.kind_label}}</option></select><button :disabled="!start||!end||!!status&&status!=='page_asserted'&&status!=='human_reviewed'">查找路径</button></div><p aria-live="polite">{{pathText||'按有据关系查找无向最短路径。共享汉字、书体不表示历史传承。'}}</p></form></div>
 <aside class="kg-panel kg-details"><header><h2>{{activeEdge?'关系与证据':'节点具体信息'}}</h2><small>{{relations.length}} 条关联记录</small></header><div class="kg-details-scroll"><template v-if="activeNode"><span class="kg-tag">{{activeNode.kind_label}}</span><h3>{{activeNode.label}}</h3><button class="kg-center-this" @click="center=activeNode.id;pathIds=[];depth=layout==='neural'&amp;&amp;depth===0?1:depth">围绕此节点展开 ↗</button><dl class="kg-node-facts"><template v-for="[key,value] in nodeFacts"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl><a v-if="activeNode.attributes.url" :href="activeNode.attributes.url" target="_blank" rel="noopener noreferrer">打开原始资料 ↗</a><p v-if="activeNode.kind==='resource'">平台入口已登记。这不表示整库已导入。</p><details v-for="receipt in data?.receipts.filter(d=>d.source_id===activeNode?.attributes.source_id)" class="kg-resource-receipt"><summary>{{receipt.title}} · 读取凭证</summary><a :href="receipt.url" target="_blank" rel="noopener noreferrer">打开页面 ↗</a><p>{{receipt.summary}}</p><code>SHA-256：{{receipt.sha256}}</code></details></template><template v-if="activeEdge"><h3>{{label(activeEdge.source)}} → {{label(activeEdge.target)}}</h3><span class="kg-tag">{{activeEdge.label}}</span><dl class="kg-node-facts"><dt>来源方式</dt><dd>{{activeEdge.assertion_source==='page_fetched'?'公开页面字段提取':'手工引用（未自动抓取）'}}</dd><dt>核验状态</dt><dd>{{activeEdge.review_state==='unreviewed'?'尚未人工复核':data?.statuses[activeEdge.review_state]}}</dd></dl></template>
 <article v-for="e in relations" :key="e.id" class="kg-evidence"><button class="kg-relation-button" @click="select(e.id,'edge')">{{label(e.source)}} <span>{{e.label}}</span> {{label(e.target)}}</button><b class="kg-status" :class="e.status">{{data?.statuses[e.status]}}</b><a :href="e.attributes.canonical_url||doc(e.document_id)?.url" target="_blank" rel="noopener noreferrer">{{doc(e.document_id)?.title}} ↗</a><p>{{doc(e.document_id)?.summary}}</p><small v-if="e.attributes.positions">印文位置：{{e.attributes.positions.join('、')}}（按页面文字顺序）</small><small>{{doc(e.document_id)?.fetched_at?'读取于 '+new Date(doc(e.document_id)!.fetched_at!).toLocaleString('zh-CN'):'手工引用，未自动读取网页'}}</small><details><summary>证据与核验详情</summary><code>{{doc(e.document_id)?.url}}</code><p>提取方式：{{doc(e.document_id)?.method==='public_html_metadata_extraction'?'公开页面文字字段提取':'手工录入引用'}}</p><code v-if="doc(e.document_id)?.sha256">SHA-256：{{doc(e.document_id)?.sha256}}</code><p v-if="e.reviewer">复核人：{{e.reviewer}}<br>依据：{{e.review_note}}</p></details></article>
 <form v-if="activeEdge" class="kg-review" @submit.prevent="review(activeEdge,'human_reviewed')"><h3>人工复核</h3><p>请先打开出处核对。这会记录本机复核意见，不等同于专家鉴定。</p><label>复核人<input v-model="reviewer" required minlength="2" maxlength="80" placeholder="姓名或可追溯身份"></label><label>复核依据<textarea v-model="reviewNote" required minlength="5" maxlength="1500" placeholder="记录支持或排除这条关系的具体文字"></textarea></label><div><button :disabled="saving">记为人工复核</button><button type="button" :disabled="saving||reviewer.trim().length<2||reviewNote.trim().length<5" @click="review(activeEdge,'rejected')">排除此线索</button></div></form>
 <p v-if="!relations.length" class="kg-empty-detail">该节点尚无对象级关系。可继续核对具体条目后导入线索。</p></div></aside>
 </section>
 <footer class="kg-footnote">{{data?.notice}} MySQL持久化 · Three.js三维空间 · Cytoscape.js二维布局 · RDFLib导出。光流为关系方向的视觉表达，不代表实时活动或可信度。</footer>
 <div v-if="importOpen" class="kg-modal-overlay" @keydown="modalKey" @click.self="importOpen=false"><section ref="modalEl" class="kg-modal" role="dialog" aria-modal="true" aria-labelledby="kg-import-title"><header><h2 id="kg-import-title">导入资料线索</h2><button aria-label="关闭导入" @click="importOpen=false">×</button></header><p>每条关系必须有出处，导入后统一进入“待核验”。图片不会自动变成印文或历史标签。</p><label>选择 JSON 文件<input type="file" accept="application/json,.json" @change="readFile"></label><textarea v-model="importText" aria-label="待导入的图谱JSON" spellcheck="false"></textarea><p>支持印稿、汉字、书体、类型、来源集、文献、人物、时期和地点；一次最多100条关系。模板中的占位文字请替换为实际资料。</p><p v-if="error" class="kg-error" role="alert">{{error}}</p><footer><button @click="importOpen=false">取消</button><button class="kg-primary" :disabled="saving" @click="importClaims">{{saving?'保存中…':'保存为待核验'}}</button></footer></section></div>
</main>
</template>
<style>
@font-face{font-family:MuseumSong;src:url('/assets/museum/serif-sc.woff2') format('woff2');font-display:swap;font-weight:200 900}
